/**
 * Official TCF HD Illustration Data URIs
 * Embedded Base64 for 100% instant, bulletproof image loading across all environments & Vercel deployments.
 */

export const HD_ILLUSTRATIONS: Record<string, string> = {
  "tcf_p1_q1": "data:image/png;base64,",
  "tcf_p1_q2": "data:image/png;base64,",
  "tcf_p1_q3": "data:image/png;base64,",
  "tcf_p1_q4": "data:image/png;base64,",
  "tcf_p2_q1": "data:image/png;base64,",
  "tcf_p2_q2": "data:image/png;base64,",
  "tcf_p2_q3": "data:image/png;base64,",
  "tcf_p2_q4": "data:image/png;base64,",
};

export function getHdIllustration(paperIdx: number, qNum: number): string | undefined {
  const key = `tcf_p${paperIdx}_q${qNum}`;
  return HD_ILLUSTRATIONS[key] || `/illustrations/tcf_p${paperIdx}_q${qNum}.png`;
}
